"""Seating charts: students sorted by last name, in rows."""

from itertools import count


def _sort_key(item):
    return (item.last_name, item.first_name)


def _chunks(items, size):
    for start in range(0, len(items), size):
        yield items[start:start + size]


def _row_line(index, group):
    names = " | ".join(item.display_name for item in group)
    return f"Row {index}: {names}"


# ---
def seat_rows(students, per_row):
    if per_row <= 0 or not students:
        raise ValueError("need students and a seat count")
    ordered = sorted(students, key=_sort_key)
    rows = _chunks(ordered, per_row)
    return list(map(_row_line, count(1), rows))

