import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def _pupil(last, first):
    return Student("1", last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.group = [
            _pupil("Halloway", "Juno"),
            _pupil("Thistle", "Bram"),
            _pupil("Dunmere", "Piet")
        ]

    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seat_rows(self.group, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Thistle, Bram"
            ]
        )

    def test_bad_seat_count(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows(self.group, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
